// runs inside one DB transaction
async function transfer(tx, fromId, toId, amount) {
  // lock the source, then the destination
  await tx.query(
    'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE', [fromId]);
  await tx.query(
    'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE', [toId]);

  await tx.query(
    'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
    [amount, fromId]);
  await tx.query(
    'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
    [amount, toId]);
}
